import{_ as i,C as l,o,c as h,a2 as d,b as a,w as t,a as r,E as c,a3 as n}from"./chunks/framework.CZqXuAiL.js";const w=JSON.parse('{"title":"How Detection Works","description":"The exact signals, thresholds and defaults behind all ten Protection Plus detectors — miner, port scan, DDoS, zip bomb, exploit, abuse, YARA, FIM, Trivy and on-access — and how findings get their severity.","frontmatter":{"title":"How Detection Works","description":"The exact signals, thresholds and defaults behind all ten Protection Plus detectors — miner, port scan, DDoS, zip bomb, exploit, abuse, YARA, FIM, Trivy and on-access — and how findings get their severity."},"headers":[],"relativePath":"protection/user-guide/detection.md","filePath":"protection/user-guide/detection.md","lastUpdated":null}'),p={name:"protection/user-guide/detection.md"};function g(u,e,m,b,f,v){const s=l("Mermaid");return o(),h("div",null,[e[3]||(e[3]=d('<h1 id="how-detection-works" tabindex="-1">How Detection Works <a class="header-anchor" href="#how-detection-works" aria-label="Permalink to &quot;How Detection Works&quot;">​</a></h1><p>Each detector inspects a shared per-tick <a href="./../architecture/overview">system snapshot</a> (default tick: <code>scan_interval: 5s</code>) and emits <code>Event</code>s with a severity. This page explains exactly what each one checks and the real default thresholds, so you can trust — and tune — the results.</p><h2 id="severity-events" tabindex="-1">Severity &amp; events <a class="header-anchor" href="#severity-events" aria-label="Permalink to &quot;Severity &amp; events&quot;">​</a></h2><p>Every finding carries a severity:</p><table tabindex="0"><thead><tr><th>Severity</th><th>Meaning</th></tr></thead><tbody><tr><td><code>info</code></td><td>Informational only</td></tr><tr><td><code>low</code></td><td>Weak signal, worth noting</td></tr><tr><td><code>medium</code></td><td>Suspicious, likely worth a look</td></tr><tr><td><code>high</code></td><td>Strong signal, very likely malicious</td></tr><tr><td><code>critical</code></td><td>Multiple strong signals — almost certainly malicious</td></tr></tbody></table><p>Events flow into the <a href="./../architecture/overview">engine</a>, which de-duplicates them (per <code>cooldown</code>, default 5m), filters by <a href="./../configuration/reference#modes">mode</a>, and matches them against your <a href="./actions-rules">rules</a>.</p><hr><h2 id="⛏️-miner-detection" tabindex="-1">⛏️ Miner detection <a class="header-anchor" href="#⛏️-miner-detection" aria-label="Permalink to &quot;⛏️ Miner detection&quot;">​</a></h2><p>Three independent signals, escalating in severity when combined.</p>',9)),(o(),a(n,null,{default:t(()=>[c(s,{id:"mermaid-76",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20P%5BProcess%20snapshot%5D%20--%3E%20S%7BKnown%20binary%3F%3Cbr%2F%3Ecomm%20%2F%20exe%20%2F%20miner%20args%7D%0A%20%20%20%20P%20--%3E%20C%7BSustained%20CPU%3F%3Cbr%2F%3E%E2%89%A5%2085%25%20of%20one%20core%20for%2045s%7D%0A%20%20%20%20N%5BConnections%5D%20--%3E%20POOL%7BEstablished%20to%20a%20pool%20port%3Cbr%2F%3Eon%20a%20PUBLIC%20IP%3F%7D%0A%20%20%20%20S%20--%3E%7Cyes%7C%20H%5BHIGH%5D%0A%20%20%20%20C%20--%3E%7Cyes%7C%20MED%5BMEDIUM%5D%0A%20%20%20%20S%20--%3E%7Cyes%7C%20AND%7Bboth%3F%7D%0A%20%20%20%20C%20--%3E%7Cyes%7C%20AND%0A%20%20%20%20AND%20--%3E%7Cyes%7C%20CRIT%5BCRITICAL%5D%0A%20%20%20%20POOL%20--%3E%7Cyes%7C%20H2%5BHIGH%5D%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[r(" Loading... ",-1)])]),_:1})),e[4]||(e[4]=d('<ol><li><strong>Signature</strong> — the process&#39;s <code>comm</code> or exe basename matches a known miner (xmrig, minerd, t-rex, nbminer, lolminer, srbminer, …), or its command line carries a miner <strong>argument</strong> fingerprint: <code>stratum+tcp</code>, <code>stratum+ssl</code>, <code>--donate-level</code>, <code>--coin </code>, <code>--randomx</code>, <code>-o pool.</code>, <code>--algo </code>, <code>--cpu-priority</code>, <code>--nicehash</code>. Binary names are matched only against <code>comm</code> and the exe basename (the actual process identity), never the raw command line — so a parent shell that merely references the path isn&#39;t flagged. Command-line matching is reserved for argument fingerprints a launcher wouldn&#39;t legitimately carry.</li><li><strong>Sustained CPU</strong> — per-core CPU% is computed from jiffy deltas between snapshots (<code>delta_jiffies / (elapsed × clock_ticks) × 100</code>). If it stays at or above <code>cpu_threshold</code> (default <strong>85%</strong> of one core) for <code>sustained_seconds</code> (default <strong>45s</strong>), that alone is flagged — this catches <strong>unknown/custom</strong> miners. Processes on the game-server whitelist (<code>java</code>, <code>bedrock_server</code>, <code>srcds_linux</code>, <code>RustDedicated</code>, <code>valheim_server</code>, …) are exempt from this heuristic path, but are still caught by signature matching.</li><li><strong>Pool connection</strong> — an <em>established</em> connection whose remote port is in <code>pool_ports</code> (default <code>3333, 4444, 5555, 7777, 8888, 9999, 14444, 14433, 45700, 45560, 20580</code>) <strong>and</strong> whose remote IP is a routable public address. Loopback/private/link-local destinations on those ports are local services (redis, HTTP-alt, …) and are deliberately ignored. Works for host <em>and</em> container connections.</li><li><strong>Masked binary</strong> — a process running from a <strong>deleted</strong> on-disk executable (exe ends in <code> (deleted)</code>) while sustaining high CPU is a classic miner evasion technique.</li></ol><p><strong>Severity escalation:</strong></p><table tabindex="0"><thead><tr><th>Signals</th><th>Severity</th><th>Title</th></tr></thead><tbody><tr><td>Signature <strong>and</strong> sustained CPU</td><td><code>critical</code></td><td>Cryptocurrency miner running</td></tr><tr><td>Masked (deleted exe) + sustained CPU</td><td><code>high</code></td><td>Masked process burning CPU</td></tr><tr><td>Signature only</td><td><code>high</code></td><td>Known miner binary detected</td></tr><tr><td>Sustained CPU only</td><td><code>medium</code></td><td>Sustained high CPU usage</td></tr><tr><td>Pool-port connection (public IP)</td><td><code>high</code></td><td>Connection to mining pool port</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">TUNING</p><p>False positives from a legitimately busy server? Raise <code>sustained_seconds</code> first, then <code>cpu_threshold</code>, or add the process to the miner&#39;s <code>whitelist_processes</code>. Signature and pool-connection detection keep working regardless.</p></div><hr><h2 id="🔭-port-scan-detection" tabindex="-1">🔭 Port-scan detection <a class="header-anchor" href="#🔭-port-scan-detection" aria-label="Permalink to &quot;🔭 Port-scan detection&quot;">​</a></h2><p>A scanner fans out many half-open (<code>SYN_SENT</code>) connections to many ports/hosts quickly. Only <code>SYN_SENT</code> sockets count — established or listening sockets never feed this detector.</p><ul><li>Per <strong>pid</strong>, distinct destination <strong>ports</strong> and <strong>hosts</strong> are accumulated in maps, each entry time-stamped, over a sliding <code>window</code> (default <strong>15s</strong>). Entries older than the window are pruned; pids whose state empties are dropped.</li><li>Reaching <code>distinct_ports</code> (default <strong>100</strong>) <strong>or</strong> <code>distinct_hosts</code> (default <strong>50</strong>) within the window flags a scan at <code>medium</code> severity.</li><li>A known scanner binary — matched on <code>comm</code> only (<code>nmap</code>, <code>masscan</code>, <code>zmap</code>, <code>unicornscan</code>, <code>hping3</code>, <code>naabu</code>, <code>rustscan</code>) — is flagged at <code>high</code> severity (&quot;Network scanner running&quot;) regardless of counts.</li><li>Container scans are attributed to the container (read from the container&#39;s own network namespace); if the connection carries no container ID, the pid&#39;s cgroup is checked.</li></ul><p>The event evidence reports the exact <code>distinct_ports</code> and <code>distinct_hosts</code> counts and the window, so you can sanity-check a flag at a glance.</p><hr><h2 id="🌊-ddos-detection" tabindex="-1">🌊 DDoS detection <a class="header-anchor" href="#🌊-ddos-detection" aria-label="Permalink to &quot;🌊 DDoS detection&quot;">​</a></h2><p>Three angles, so both crude and sophisticated outbound floods are caught.</p><table tabindex="0"><thead><tr><th>Signal</th><th>How</th><th>Default</th></tr></thead><tbody><tr><td><strong>Container egress rate</strong></td><td>Per-container packets/sec and bytes/sec, computed from deltas between two <code>docker stats</code> one-shot samples (TxPackets/TxBytes summed across all interfaces). Crossing <code>pps_threshold</code> <strong>or</strong> <code>bps_threshold</code> ⇒ <code>high</code>.</td><td><code>pps_threshold: 60000</code>, <code>bps_threshold: 125000000</code> (~1 Gbit/s)</td></tr><tr><td><strong>Tool signatures</strong></td><td>Known stress tools (<code>hping3</code>, <code>t50</code>, <code>mhddos</code>, <code>slowloris</code>, <code>goldeneye</code>, <code>torshammer</code>, <code>xerxes</code>, <code>loic</code>/<code>hoic</code>/<code>xoic</code>, <code>hulkattack</code>, …) matched on <code>comm</code>/exe basename exactly, and against the command line with <strong>word-boundary</strong> matching so generic fragments never fire (e.g. <code>byte</code> inside <code>-byteswappedclients</code>). ⇒ <code>high</code>.</td><td><code>known_tools</code> list</td></tr><tr><td><strong>Java flooder heuristic</strong></td><td>If <code>comm</code> starts with <code>java</code> and the cmdline contains <code>ddos</code>, <code>booter</code>, <code>stresser</code>, <code>flood</code> or <code>doser</code> (the classic <code>java -jar ddos.jar</code> pattern on game nodes) ⇒ <code>high</code>.</td><td>always on</td></tr><tr><td><strong>Connection floods</strong></td><td>A single pid holding ≥ <code>conn_threshold</code> simultaneous outbound sockets — TCP counts established + half-open, UDP counts any non-listening socket (remote port &gt; 0), since amplification floods are UDP-heavy. Game-server-whitelisted pids are skipped. ⇒ <code>high</code>.</td><td><code>conn_threshold: 1500</code></td></tr></tbody></table><p>Stale containers are dropped from the rate sampler each tick, so a removed container never emits phantom events.</p><div class="info custom-block"><p class="custom-block-title">GAME-NODE REALITY</p><p>Java-hosted &quot;booter&quot; jars are a common abuse vector on Minecraft nodes — the DDoS detector specifically fingerprints <code>java -jar</code> flooders in addition to native tools, while the game-server whitelist keeps real busy servers out of the connection-flood heuristic.</p></div><hr><h2 id="💣-zip-bomb-detection" tabindex="-1">💣 Zip-bomb detection <a class="header-anchor" href="#💣-zip-bomb-detection" aria-label="Permalink to &quot;💣 Zip-bomb detection&quot;">​</a></h2><p>Protection reads an archive&#39;s <strong>declared</strong> sizes from its metadata and <strong>never extracts</strong> it, so detection is safe and cheap. It catches both classic nested bombs and modern overlapping/quine bombs.</p>',18)),(o(),a(n,null,{default:t(()=>[c(s,{id:"mermaid-294",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20HOT%5BProcess%20GROUP%3A%20%E2%89%A580%25%20CPU%20%2B%20%E2%89%A525%20MiB%2Fs%20writes%5D%20--%3E%7Cactive%20extraction%7C%20OPEN%5B%22Inspect%20open%20archives%20%2B%20cwd%3Cbr%2F%3Evia%20%2Fproc%2F%26lt%3Bpid%26gt%3B%2Froot%22%5D%0A%20%20%20%20SWEEP%5BFull%20sweep%20every%2030m%5D%20--%3E%20WALK%5BWalk%20scan_paths%3Cbr%2F%3Eworker%20pool%20of%204%2C%205m%20budget%5D%0A%20%20%20%20OPEN%20--%3E%20CHECK%7Bratio%20%E2%89%A5%20150%3Cbr%2F%3Eor%20uncompressed%20%E2%89%A5%2050%20GiB%3F%7D%0A%20%20%20%20WALK%20--%3E%20CHECK%0A%20%20%20%20CHECK%20--%3E%7Cyes%7C%20BOMB%5BFlag%20bomb%3Cbr%2F%3Emedium%3B%20high%20if%20ratio%20%E2%89%A5%201500%20or%20size%20ceiling%5D%0A"})]),fallback:t(()=>[...e[1]||(e[1]=[r(" Loading... ",-1)])]),_:1})),e[5]||(e[5]=d('<p><strong>How each format is measured (metadata first, extraction never):</strong></p><table tabindex="0"><thead><tr><th>Format</th><th>Method</th></tr></thead><tbody><tr><td><code>zip</code> / <code>jar</code></td><td>Sum of <code>UncompressedSize64</code> across the central directory — essentially free.</td></tr><tr><td><code>gzip</code> / <code>tgz</code></td><td>The 4-byte ISIZE trailer (uncompressed size mod 2³²). If the claimed size is <em>smaller</em> than the compressed file, the value has wrapped past 2³² — a real gzip stream never shrinks its input — so Protection falls back to a bounded probe.</td></tr><tr><td><code>tar</code></td><td>Walk headers and sum member sizes (context-cancellable).</td></tr><tr><td><code>7z</code>, <code>rar</code></td><td>Sum declared sizes from the archive headers.</td></tr><tr><td><code>xz</code>, <code>bzip2</code> (and wrapped gzip)</td><td><strong>Bounded probe:</strong> decompress at most <code>probe_compressed_limit</code> (default <strong>1 MiB</strong>) of input, stop after <code>probe_uncompressed_limit</code> (default <strong>10 MiB</strong>) of output or timeout, then extrapolate the total from the <strong>actual consumed-to-produced ratio</strong> × the file&#39;s real size.</td></tr></tbody></table><p>A file is a bomb when <code>uncompressed ÷ compressed ≥ ratio_threshold</code> (default <strong>150</strong>) <strong>or</strong> <code>uncompressed ≥ max_uncompressed</code> (default <strong>50 GiB</strong>). Severity is <code>medium</code>, escalating to <code>high</code> when the ratio is ≥ 10× the threshold or the absolute ceiling is hit.</p><p><strong>Two ways archives get inspected:</strong></p><ul><li><strong>Hot trigger (event-driven, on by default):</strong> CPU and disk-write rates are aggregated per <strong>process group</strong> — because real extractions are pipelines: <code>tar xzf</code> burns CPU in the gzip child while the tar parent does the writes, and neither alone trips a per-pid check. When a group exceeds <code>hot_cpu_percent</code> (default <strong>80%</strong>) <em>and</em> <code>hot_write_mbps</code> (default <strong>25 MiB/s</strong>), Protection immediately inspects every archive the group has open plus the archives in each member&#39;s working directory. A bomb is caught <strong>mid-unzip in seconds</strong>, not after a fixed delay.</li><li><strong>Full sweep (backstop):</strong> every <code>full_scan_interval</code> (default <strong>30m</strong>), a walk of <code>scan_paths</code> (default <code>/var/lib/pterodactyl/volumes</code>) catches bombs uploaded but not yet extracted. The sweep runs a worker pool of <code>max_concurrent_inspects</code> (default <strong>4</strong>) under a <code>full_scan_max_duration</code> time budget (default <strong>5m</strong>), skips archives smaller than <code>min_compressed_size</code> (default <strong>10 KiB</strong>) and any file whose mtime is unchanged since it was last cleared, and caps each archive inspection at <code>inspect_timeout</code> (default <strong>5s</strong>).</li></ul><p>For container processes, paths are translated from the container&#39;s mount namespace via <code>/proc/&lt;pid&gt;/root</code>, so the host can stat exactly what the extractor sees. Pterodactyl volume paths (<code>/var/lib/pterodactyl/volumes/&lt;server-uuid&gt;/…</code>) are mapped back to the owning server UUID for suspension/quarantine.</p><hr><h2 id="🐚-exploit-container-escape-detection" tabindex="-1">🐚 Exploit &amp; container-escape detection <a class="header-anchor" href="#🐚-exploit-container-escape-detection" aria-label="Permalink to &quot;🐚 Exploit &amp; container-escape detection&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Check</th><th>How</th><th>Severity</th></tr></thead><tbody><tr><td><strong>Known exploit tools</strong></td><td><code>comm</code>/exe basename in <code>suspicious_processes</code> (default: <code>dirtycow</code>, <code>dirtypipe</code>, <code>pwnkit</code>, <code>linpeas</code>, <code>linenum</code>, <code>les.sh</code>, <code>unix-privesc-check</code>, <code>exploit</code>, <code>nsenter</code>, <code>runc</code>, <code>deepce</code>).</td><td><code>high</code></td></tr><tr><td><strong>Reverse shells</strong></td><td>Cmdline contains a <strong>network-bound</strong> pattern (<code>flag_reverse_shell</code>): <code>/dev/tcp/</code>, <code>/dev/udp/</code>, <code>nc -e</code>, <code>ncat -e</code>, <code>nc.traditional -e</code>, <code>pty.spawn</code>, <code>socat exec</code>, <code>socat tcp</code>, <code>exec:&#39;/bin</code>, <code>exec 5&lt;&gt;/dev/tcp</code>, <code>0&lt;&amp;196</code>, <code>sh -i &gt;&amp; /dev</code>, <code>bash -i &gt;&amp;</code>, <code>-i &gt;&amp; /dev/tcp</code>. Bare <code>bash -i</code>/<code>sh -i</code> are deliberately excluded — interactive login shells use them legitimately.</td><td><code>high</code></td></tr><tr><td><strong>Privilege escalation</strong></td><td>Cmdline contains a privesc pattern (<code>flag_privilege_escalation</code>): <code>chmod +s</code>, <code>chmod u+s</code>, <code>chmod 4755</code>, <code>chmod 6755</code>, <code>setcap cap_</code>, <code>&gt;&gt; /etc/sudoers</code>, <code>&gt;/etc/sudoers</code>, <code>usermod -ag sudo</code>, <code>usermod -g 0</code>, <code>nsenter --target 1</code>, <code>nsenter -t 1</code>, <code>--mount=/proc/1/ns</code>.</td><td><code>high</code></td></tr><tr><td><strong>nsenter escape</strong></td><td>The same privesc match, but the process is <strong>inside a container</strong> and the cmdline mentions <code>nsenter</code> or a namespace path — a textbook container-escape attempt.</td><td><code>critical</code></td></tr><tr><td><strong>Setuid walk</strong></td><td>A periodic walk of <code>watch_paths</code> (default <code>/tmp</code>, <code>/dev/shm</code>, <code>/var/tmp</code>) flags any file with the setuid/setgid bit — a privesc payload on disk. Bounded by <code>limits.max_setuid_walk_files</code>; whitelisted paths skipped.</td><td><code>high</code></td></tr><tr><td><strong>Execution from scratch</strong></td><td>A process whose exe lives under a watch path (world-writable scratch dirs) — a classic dropper/stager pattern. The <code> (deleted)</code> suffix is stripped before matching, so self-deleting droppers still match.</td><td><code>medium</code></td></tr></tbody></table><p>The setuid walk caches directory mtimes (<code>limits.cache_directory_mtimes</code>) so unchanged trees are not re-walked every tick.</p><hr><h2 id="🕸️-abuse-detection" tabindex="-1">🕸️ Abuse detection <a class="header-anchor" href="#🕸️-abuse-detection" aria-label="Permalink to &quot;🕸️ Abuse detection&quot;">​</a></h2><p>Flags hosting-abuse patterns that aren&#39;t outright exploits but will get a provider in trouble: Tor exits, proxy/VPN tunnels, customer-installed mail servers (spam), and execution out of upload directories.</p><ul><li><strong>Known services</strong> — <code>comm</code>/exe basename in <code>known_processes</code> (default: <code>tor</code>, <code>openvpn</code>, <code>wireguard</code>, <code>softether</code>, <code>shadowsocks</code>, <code>ss-server</code>, <code>v2ray</code>, <code>xray</code>, <code>trojan</code>, <code>hysteria</code>, <code>sing-box</code>, <code>cloudflared</code>, <code>frpc</code>/<code>frps</code>, <code>ngrok</code>, <code>sendmail</code>, <code>postfix</code>, <code>exim4</code>, <code>dovecot</code>, <code>znc</code>, <code>eggdrop</code>, …) ⇒ <code>high</code>.</li><li><strong>Cmdline patterns</strong> — substrings from <code>known_cmd_patterns</code> (<code>--socksport</code>, <code>--orport</code>, <code>--dirport</code>, <code>-c /etc/tor</code>, <code>/etc/openvpn</code>, <code>--protocol trojan|vmess|vless</code>, <code>inbound:</code>, <code>outbound:</code>, <code>listen=0.0.0.0</code>, …) ⇒ <code>high</code>. The event records which kind of signature hit (<code>known_abuse_process</code> vs <code>cmd_pattern</code>).</li><li><strong>Abusive listening ports</strong> — a process with a <strong>listening</strong> TCP socket (remote port 0) on a port in <code>abusive_ports</code> (default: Tor <code>9001/9030/9050/9051/9150/9151</code>, SOCKS <code>1080/1081/1090</code>, proxy <code>7890/7891/8000/8001/8008/8082</code>, Shadowsocks <code>8388/8389</code>, Trojan/Xray <code>4433/8443</code>, hysteria/sing-box <code>10086/12345/54321</code>) ⇒ <code>high</code>.</li><li><strong>Execution from upload dirs</strong> — a process whose exe lives under <code>watch_upload_paths</code> (default: <code>/var/lib/pterodactyl/volumes</code>, <code>/var/lib/pterodactyl/mounts</code>, <code>/home/container</code>, <code>/tmp</code>, <code>/var/tmp</code>, <code>/dev/shm</code>) — how customers run miners/proxies after a panel upload ⇒ <code>medium</code>.</li></ul><p>The abuse <code>whitelist_processes</code> (default: the game-server list) suppresses all four checks for legitimate servers.</p><hr><h2 id="🧬-yara-sweep" tabindex="-1">🧬 YARA sweep <a class="header-anchor" href="#🧬-yara-sweep" aria-label="Permalink to &quot;🧬 YARA sweep&quot;">​</a></h2><p>An interval-gated full sweep that shells out to the <code>yara</code> CLI (<code>yara -r -f &lt;rules_dir&gt; &lt;path&gt;</code>) — no Go bindings, so the daemon stays a CGO-free static binary.</p><ul><li>Runs at most every <code>interval</code> (default <strong>10m</strong>; the first pass always runs) over <code>scan_paths</code> (default <code>/var/lib/pterodactyl/volumes</code>) with rules from <code>rules_dir</code> (default <code>/etc/protection/yara</code>).</li><li>Each yara invocation is capped at <strong>2 minutes</strong> so a huge tree can&#39;t stall the scan loop. Yara&#39;s exit code 1 means &quot;no matches&quot; and is treated as the normal case; any other failure is logged so a broken ruleset never goes silently blind.</li><li>Each match line (<code>RULE_NAME FILE_PATH</code>) becomes a <code>high</code>-severity event (category <code>abuse</code>). If the matched file is currently executing, the event is annotated with the pid, process and container so actions can target it directly.</li><li><strong>Graceful no-op:</strong> if the <code>yara</code> binary isn&#39;t in <code>PATH</code>, the detector disables itself permanently and <code>Run</code> returns nothing.</li></ul><hr><h2 id="🧷-file-integrity-monitoring-fim" tabindex="-1">🧷 File-integrity monitoring (FIM) <a class="header-anchor" href="#🧷-file-integrity-monitoring-fim" aria-label="Permalink to &quot;🧷 File-integrity monitoring (FIM)&quot;">​</a></h2><p>SHA-256 baselines of the files an attacker most wants to tamper with.</p><ul><li>Default watch set: <strong>the daemon&#39;s own binary and its config file</strong> (plus anything you add to <code>paths</code>).</li><li>Hashing happens at most every <code>interval</code> (default <strong>5m</strong>); the first pass always runs. Files are streamed through SHA-256, so multi-gigabyte files never load into memory.</li><li>The first sighting of a path <strong>records the baseline silently</strong> — no alert for pre-existing state. A later content change raises a <code>high</code>-severity event (&quot;Protected file modified&quot;, with old/new hash prefixes as evidence) and the new hash <strong>becomes the baseline</strong>, so each change alerts exactly once instead of re-alerting every interval.</li><li>Missing or unreadable files are skipped silently.</li></ul><hr><h2 id="🛡️-image-vulnerability-scanning-trivy" tabindex="-1">🛡️ Image vulnerability scanning (Trivy) <a class="header-anchor" href="#🛡️-image-vulnerability-scanning-trivy" aria-label="Permalink to &quot;🛡️ Image vulnerability scanning (Trivy)&quot;">​</a></h2><p>Per-image CVE counts via the <code>trivy</code> CLI.</p><ul><li>Runs at most every <code>interval</code> (default <strong>1h</strong>) against the distinct images of running containers (via the Docker API), falling back to <code>docker image ls</code> when no API client is available. Dangling <code>&lt;none&gt;</code> images are skipped.</li><li>Each image is scanned with <code>trivy image --quiet --format json --severity HIGH,CRITICAL</code>, capped at <strong>2 minutes</strong> per image.</li><li>An image with any HIGH/CRITICAL findings raises an event with the counts and the top 5 CVE IDs as evidence: <code>medium</code> when only HIGHs exist, <code>high</code> when at least one CRITICAL exists.</li><li><strong>Graceful no-op:</strong> if the <code>trivy</code> binary isn&#39;t in <code>PATH</code>, the detector logs once at startup and never scans.</li></ul><hr><h2 id="⚡-on-access-scanning" tabindex="-1">⚡ On-access scanning <a class="header-anchor" href="#⚡-on-access-scanning" aria-label="Permalink to &quot;⚡ On-access scanning&quot;">​</a></h2><p>The fast path: files are scanned the moment they&#39;re created or modified in the watched upload paths, long before any periodic sweep would see them.</p>',30)),(o(),a(n,null,{default:t(()=>[c(s,{id:"mermaid-589",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20FS%5Bfsnotify%20create%2Fwrite%3Cbr%2F%3Erecursive%20watch%5D%20--%3E%20DEB%5BSettle%20debounce%3Cbr%2F%3E500ms%20quiet%5D%0A%20%20%20%20DEB%20--%3E%20POOL%5BScan%20worker%3Cbr%2F%3Emax%202%20concurrent%5D%0A%20%20%20%20POOL%20--%3E%20HASH%7BSHA-256%20in%3Cbr%2F%3Eblocklist%3F%7D%0A%20%20%20%20HASH%20--%3E%7Cyes%7C%20CRIT%5BCRITICAL%3A%20known%20malware%5D%0A%20%20%20%20HASH%20--%3E%7Cno%7C%20YARA%7BYARA%20match%3F%7D%0A%20%20%20%20YARA%20--%3E%7Cyes%7C%20HIGH%5BHIGH%3A%20rule%20match%5D%0A"})]),fallback:t(()=>[...e[2]||(e[2]=[r(" Loading... ",-1)])]),_:1})),e[6]||(e[6]=d('<ul><li><strong>Recursive watch</strong> — every <code>watch_paths</code> root (default: the upload paths) and all existing subdirectories get inotify watches; newly created directories are added on the fly, so a tree moved into place can&#39;t hide.</li><li><strong>Settle debounce</strong> — editors and downloaders write in bursts; a path is only scanned once it has been quiet for <code>settle_ms</code> (default <strong>500ms</strong>), so Protection never scans a half-written file.</li><li><strong>Bounded workers</strong> — scans run in a pool capped at <strong>2 concurrent</strong> scans, decoupled from the engine tick; <code>Run</code> just drains whatever the workers found. The event queue holds at most <strong>1000</strong> events; beyond that the oldest are dropped (with a warning) so a write storm can&#39;t grow memory.</li><li><strong>Hash blocklist first</strong> — files up to <strong>512 MiB</strong> are streamed through SHA-256 and looked up in the threat-intel blocklist (MalwareBazaar recent export by default). A match is <code>critical</code> — a known-bad payload.</li><li><strong>Then YARA</strong> — files up to <strong>64 MiB</strong> are scanned (30s timeout) against the compiled <code>protection.yar</code> bundle the intel updater maintains, falling back to a recursive scan of the whole rules directory. A match is <code>high</code>.</li><li>Both checks are independently toggleable (<code>hash_check</code>, <code>yara_check</code>, both default on); the YARA half silently disables when the binary or rules dir is absent. Whitelisted paths are skipped.</li></ul><hr><h2 id="false-positive-design" tabindex="-1">False-positive design <a class="header-anchor" href="#false-positive-design" aria-label="Permalink to &quot;False-positive design&quot;">​</a></h2><p>Protection Plus is built for game-hosting nodes, where the loudest legitimate workloads look a lot like abuse. Every heuristic that could fire on a busy server has a deliberate guard:</p><ul><li><strong>Game-server whitelists.</strong> The miner&#39;s sustained-CPU path, the DDoS connection-flood path and all abuse checks skip <code>java</code>, <code>bedrock_server</code>, <code>srcds_linux</code>, <code>RustDedicated</code>, <code>valheim_server</code>, and ~25 other known server binaries by default (<code>whitelist_processes</code>, extendable per detector).</li><li><strong>Public-IP-only pool checks.</strong> Miner pool-port detection ignores loopback/private/link-local destinations, so local redis or HTTP-alt services on ports like 3333/8888 never flag.</li><li><strong>Word-boundary matching.</strong> DDoS tool names match the command line only as whole words — <code>byte</code> can&#39;t fire on <code>-byteswappedclients</code>, and the default list deliberately excludes short/generic tokens (<code>hammer</code>, <code>loris</code>, <code>hulk</code>).</li><li><strong>Network-bound-only reverse-shell signatures.</strong> <code>bash -i</code> alone is never flagged; a shell must redirect to a socket (<code>/dev/tcp</code>, <code>nc -e</code>, <code>socat exec</code>, …) to match.</li><li><strong>comm/exe-only binary matching.</strong> Known-binary lists (miners, scanners, stress tools, exploit tools, abuse services) match the process identity — <code>comm</code> and the exe basename — never arbitrary command lines, so referencing a path in a script or grep is harmless.</li><li><strong>Baseline-first FIM.</strong> Existing files are baselined silently; only <em>changes</em> alert, and each change alerts exactly once.</li><li><strong>Physical bounds.</strong> Zip-bomb sweeps ignore archives under 10 KiB and cap each inspection at 5s; on-access scanning debounces half-written files and caps file sizes; port-scan state expires with its window.</li><li><strong>Global whitelist.</strong> <code>whitelist.paths</code> exempts whole trees from every scanner; <code>whitelist.containers</code> exempts containers by name or ID from being flagged, killed, or suspended.</li></ul><h2 id="severity-→-action-mapping" tabindex="-1">Severity → action mapping <a class="header-anchor" href="#severity-→-action-mapping" aria-label="Permalink to &quot;Severity → action mapping&quot;">​</a></h2><p>Detection decides <em>what</em> fired; <a href="./actions-rules">rules</a> decide <em>what happens</em>. The built-in default policy (<code>DefaultRules</code>) is aggressive on unambiguous threats and alert-only on noisier heuristics:</p><table tabindex="0"><thead><tr><th>Category</th><th>Min severity</th><th>Default actions</th></tr></thead><tbody><tr><td><code>miner</code></td><td><code>high</code></td><td><code>neutralize</code>, <code>suspend_server</code>, <code>alert</code></td></tr><tr><td><code>ddos</code></td><td><code>high</code></td><td><code>neutralize</code>, <code>suspend_server</code>, <code>alert</code></td></tr><tr><td><code>abuse</code> (incl. YARA sweep matches)</td><td><code>high</code></td><td><code>neutralize</code>, <code>suspend_server</code>, <code>alert</code></td></tr><tr><td><code>malware</code> (on-access hash/YARA hits)</td><td><code>high</code></td><td><code>quarantine_file</code>, <code>alert</code></td></tr><tr><td><code>exploit</code></td><td><code>high</code></td><td><code>neutralize</code>, <code>alert</code></td></tr><tr><td><code>zipbomb</code></td><td><code>medium</code></td><td><code>quarantine_file</code>, <code>alert</code></td></tr><tr><td><code>portscan</code></td><td><code>medium</code></td><td><code>alert</code></td></tr><tr><td><code>*</code> (catch-all: FIM, Trivy, everything else)</td><td><code>low</code></td><td><code>alert</code></td></tr></tbody></table><p>Rules are evaluated top to bottom and every matching rule contributes its actions, so the catch-all always alerts even when a more specific rule also fired. <code>neutralize</code> auto-selects container-kill or process-kill based on the threat, so one rule works on both Pterodactyl/Docker nodes and bare VPS hosts. See <a href="./actions-rules">Actions &amp; Rules</a> to customize.</p><h2 id="container-vs-host-attribution" tabindex="-1">Container vs host attribution <a class="header-anchor" href="#container-vs-host-attribution" aria-label="Permalink to &quot;Container vs host attribution&quot;">​</a></h2><p>Containers have their own network namespace, so their sockets never appear in the host&#39;s <code>/proc/net/tcp</code>. Protection reads each container&#39;s namespace directly, so connection-based signals (pool connections, port scans, connection floods) work for containers <strong>and</strong> are attributed to the right container — verifiable with <a href="./cli#protection-debug-conns"><code>protection debug-conns</code></a>.</p><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next steps&quot;">​</a></h2><ul><li><strong><a href="./actions-rules">Actions &amp; Rules →</a></strong> — turn findings into enforcement.</li><li><strong><a href="./../configuration/reference">Configuration reference →</a></strong> — every threshold named on this page.</li><li><strong><a href="./../architecture/overview">Architecture →</a></strong> — the snapshot and engine internals.</li></ul>',13))])}const k=i(p,[["render",g]]);export{w as __pageData,k as default};
